-- =============================================================================
-- Candidate Management Desktop - Catálogo completo de municipios de Colombia
-- Fuente: DANE, "DIVIPOLA - Códigos municipios" en datos.gov.co (dataset gdxc-w37w),
-- actualizado el 24/01/2025 y descargado el 19/11/2026.
-- 1122 registros: 1103 municipios, 18 áreas no municipalizadas (Amazonas, Guainía
-- y Vaupés) y 1 isla (San Andrés).
--
-- Se usa MERGE: si el municipio ya existe (por ejemplo los de 04-seed.sql) solo
-- actualiza el nombre, y si no existe lo inserta. Se puede ejecutar varias veces.
-- =============================================================================

-- 05 ANTIOQUIA
MERGE INTO MUNICIPIO M USING (SELECT '05001' ID, '05' DEP, 'MEDELLÍN' NOM FROM DUAL) S ON (M.MUNICIPIO_ID = S.ID) WHEN MATCHED THEN UPDATE SET M.NOMBRE = S.NOM WHEN NOT MATCHED THEN INSERT (MUNICIPIO_ID, DEPARTAMENTO_ID, NOMBRE) VALUES (S.ID, S.DEP, S.NOM);
